NEW = {
 'ui.eng34-bleed': ('Every melee hit it lands adds {n} Bleed.', {'fr': 'Chaque coup de mêlée qui porte ajoute {n} Saignement.', 'de': 'Jeder Nahkampftreffer fügt {n} Blutung hinzu.', 'es': 'Cada golpe cuerpo a cuerpo que acierta añade {n} de Sangrado.', 'it': 'Ogni colpo in mischia a segno aggiunge {n} Sanguinamento.', 'pt': 'Cada golpe corpo a corpo que acerta adiciona {n} de Sangramento.', 'tl': 'Bawat tumamang malapitang hampas ay nagdaragdag ng {n} Pagdurugo.', 'ta': 'அது இலக்கில் படும் ஒவ்வொரு அருகாமைத் தாக்கும் {n} இரத்தப்போக்கு சேர்க்கும்.', 'id': 'Setiap serangan jarak dekat yang kena menambah {n} Pendarahan.', 'zh-Hans': '它每次命中的近战攻击附加 {n} 层流血。', 'zh-Hant': '它每次命中的近戰攻擊附加 {n} 層流血。', 'ja': '近接攻撃が当たるたびに出血{n}を与える。', 'ko': '근접 공격이 명중할 때마다 출혈을 {n} 더해요.'}),
 'ui.eng34-fletcher': ("Your units' ranged shots deal {n} more damage.", {'fr': 'Les tirs à distance de vos unités infligent {n} dégâts de plus.', 'de': 'Die Fernschüsse deiner Einheiten verursachen {n} Schaden mehr.', 'es': 'Los disparos a distancia de tus unidades infligen {n} de daño más.', 'it': 'I tiri a distanza delle tue unità infliggono {n} danni in più.', 'pt': 'Os disparos à distância das suas unidades causam {n} de dano a mais.', 'tl': 'Ang malayuang tira ng mga yunit mo ay {n} na mas malakas.', 'ta': 'உங்கள் அலகுகளின் தொலைவுத் தாக்குகள் {n} கூடுதல் சேதம் செய்யும்.', 'id': 'Tembakan jarak jauh unitmu memberi {n} kerusakan lebih.', 'zh-Hans': '你方单位的远程射击多造成 {n} 点伤害。', 'zh-Hant': '你方單位的遠程射擊多造成 {n} 點傷害。', 'ja': '味方ユニットの遠隔攻撃のダメージが{n}増える。', 'ko': '아군 유닛의 원거리 공격이 {n} 더 피해를 줘요.'}),
 'ui.eng34-fletcher-long': ("While it is on the field, your units' ranged shots (arrows, bolts and spits, missiles, thrown hits) deal {n} more damage (its own too).", {'fr': 'Tant qu’il est sur le terrain, les tirs à distance de vos unités (flèches, carreaux et crachats, missiles, lancers) infligent {n} dégâts de plus (les siens aussi).', 'de': 'Solange es auf dem Feld ist, verursachen die Fernschüsse deiner Einheiten (Pfeile, Geschosse und Spucke, Raketen, Würfe) {n} Schaden mehr (auch seine eigenen).', 'es': 'Mientras está en el campo, los disparos a distancia de tus unidades (flechas, proyectiles y escupitajos, misiles, lanzamientos) infligen {n} de daño más (también los suyos).', 'it': 'Finché è in campo, i tiri a distanza delle tue unità (frecce, dardi e sputi, missili, lanci) infliggono {n} danni in più (anche i suoi).', 'pt': 'Enquanto está em campo, os disparos à distância das suas unidades (flechas, projéteis e cuspes, mísseis, arremessos) causam {n} de dano a mais (os dele também).', 'tl': 'Habang nasa larangan ito, ang malayuang tira ng mga yunit mo (palaso, bolt at dura, misil, hagis) ay {n} na mas malakas (pati ang sa kanya).', 'ta': 'அது களத்தில் இருக்கும்வரை, உங்கள் அலகுகளின் தொலைவுத் தாக்குகள் (அம்புகள், எறிகணைகள், உமிழ்வுகள், ஏவுகணைகள், எறிதல்கள்) {n} கூடுதல் சேதம் செய்யும் (அதனுடையதும்).', 'id': 'Selama ia di arena, tembakan jarak jauh unitmu (panah, peluru dan semburan, misil, lemparan) memberi {n} kerusakan lebih (miliknya juga).', 'zh-Hans': '它在场时，你方单位的远程射击（箭、弹与喷吐、飞弹、投掷）多造成 {n} 点伤害（包括它自己的）。', 'zh-Hant': '它在場時，你方單位的遠程射擊（箭、彈與噴吐、飛彈、投擲）多造成 {n} 點傷害（包括它自己的）。', 'ja': '場にいる間、味方ユニットの遠隔攻撃（矢、弾や吐きかけ、ミサイル、投てき）のダメージが{n}増える（自身のものも）。', 'ko': '필드에 있는 동안 아군 유닛의 원거리 공격(화살, 탄과 침, 미사일, 투척)이 {n} 더 피해를 줘요(자신의 것도).'}),
}
TX_LINE = re.compile(r'^(\s*)"([^"]+)":\s*"((?:[^"\\]|\\.)*)"(,?)\s*$')
def jload(s): return json.loads('"' + s + '"')
def jdump(s): return json.dumps(s, ensure_ascii=False)[1:-1]
path = 'bramblewood-texts.js'; L = open(path, encoding='utf-8').read().split('\n'); renames = {}
for i, l in enumerate(L):
    m = TX_LINE.match(l)
    if not m or m.group(2) not in CHANGED: continue
    ind, key, val, comma = m.groups(); new, tr = CHANGED[key]; old = jload(val)
    if new != old: L[i] = '%s"%s": "%s"%s' % (ind, key, jdump(new), comma); renames[old] = (new, tr)
end = next(i for i, l in enumerate(L) if l.startswith('}/*TEXT-TABLE-END*/'))
have = set(TX_LINE.match(l).group(2) for l in L if TX_LINE.match(l))
add = [k for k in NEW if k not in have]
if add:
    if not L[end - 1].rstrip().endswith(','): L[end - 1] = L[end - 1].rstrip() + ','
    L[end:end] = ['  "%s": "%s"%s' % (k, jdump(NEW[k][0]), ',' if j < len(add) - 1 else '') for j, k in enumerate(add)]
open(path, 'w', encoding='utf-8').write('\n'.join(L))
for code in CODES:
    p = 'lang/%s.json' % code; d = json.load(open(p, encoding='utf-8')); out = {}
    for k, v in d.items():
        if k in renames:
            new, tr = renames[k]
            if new not in d and new not in out: out[new] = tr[code]
        else: out[k] = v
    for k in NEW:
        en = NEW[k][0]
        if en not in out: out[en] = NEW[k][1][code]
    open(p, 'w', encoding='utf-8').write(json.dumps(out, ensure_ascii=False, indent=1) + '\n')
print('texts: %d values changed, %d keys added' % (len(renames), len(add)))
